"""Do something.
    """
def do_something(a: Any, b: Any, c: Any = None) -> object {
    return (a + b) if c else 0;
}

test_blocks:
test "t0" {
    assert (do_something(1, 2, 3) == (1 + 2));;
}

test "t1" {
    assert (do_something(1, 2, 0) == 0);;
}

test "t2" {
    assert (do_something(1, 2, 3) == 3);;
}

test "t3" {
    assert (do_something(1, 2, True) == 3);;
}

test "t4" {
    assert (do_something(1, 2) == 0);;
}

test "t5" {
    assert (do_something(1, 2, 1) == 3);;
}

test "t6" {
    assert (do_something(0, 0) == 0);;
}
